import sys

values = list(map(int, sys.stdin.read().split()))
kind = values[0]
edges = {divmod(edge, 10) for edge in values[1:]}
vertices = {v for edge in edges for v in edge}
outgoing = {v: set() for v in vertices}
incoming = {v: 0 for v in vertices}
for u, v in edges:
    outgoing[u].add(v)
    incoming[v] += 1
if kind == 1:
    answer = sum(u == v or (u < v and (v, u) in edges) for u, v in edges)
elif kind == 2:
    chosen = min(vertices, key=lambda v: (-len(outgoing[v]), v))
    answer = sum(10 * chosen + v for v in outgoing[chosen])
else:
    # Each walk has one incoming and one outgoing edge at its middle vertex.
    answer = sum(incoming[v] * len(outgoing[v]) for v in vertices)
print(answer)
